package com.zpantry.recipe.api;import static com.zpantry.recipe.api.RecipeDtos.*;import com.zpantry.common.api.*;import com.zpantry.recipe.service.RecipeService;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController public class RecipeController{private final RecipeService s;public RecipeController(RecipeService s){this.s=s;}@GetMapping("/api/recipes")public PagedResponse<RecipeResponse>list(@RequestParam(defaultValue="1")int pageIndex,@RequestParam(defaultValue="10")int pageSize){return s.list(pageIndex,pageSize);}@PostMapping("/api/recipes")public ApiResponse<RecipeResponse>create(@RequestBody RecipeRequest r){return s.create(r);}@PostMapping(path="/api/v2/recipes",consumes="multipart/form-data")public ApiResponse<RecipeResponse>createV2(@ModelAttribute RecipeFormRequest r){return s.createForm(r);}@GetMapping("/api/recipes/{id}")public ApiResponse<RecipeResponse>get(@PathVariable UUID id){return s.get(id);}@PutMapping("/api/recipes/{id}")public ApiResponse<RecipeResponse>update(@PathVariable UUID id,@RequestBody RecipeRequest r){return s.update(id,r);}@PutMapping(path="/api/v2/recipes/{id}",consumes="multipart/form-data")public ApiResponse<RecipeResponse>updateV2(@PathVariable UUID id,@ModelAttribute RecipeFormRequest r){return s.updateForm(id,r);}@DeleteMapping("/api/recipes/{id}")public ApiResponse<Object>delete(@PathVariable UUID id){return s.delete(id);}}
